/// The reminders a successful delivery of `on_message` to `actor_type` (re)declares.
pub fn reminder_schedules_for(
    actor_type: &str,
    on_message: &str,
) -> impl Iterator<Item = &'static ReminderSchedule> {
    let (actor_type, on_message) = (actor_type.to_owned(), on_message.to_owned());
    REMINDER_SCHEDULES
        .iter()
        .filter(move |s| s.actor_type == actor_type && s.on_message == on_message)
}
